from solution import first_non_repeating_character


def test_issue_example_abcabc_returns_none():
    """Example asserts first_non_repeating_character("abcabc") == None."""
    assert first_non_repeating_character("abcabc") is None  # a:1+1=2, b:1+1=2, c:1+1=2 => no 1s => None


def test_issue_empty_string_returns_none():
    """Empty string has no non-repeated character so result is None."""
    assert first_non_repeating_character("") is None  # len 0+0=0 chars => no 1s => None


def test_issue_single_character_returns_itself():
    """Find the first non-repeated character in a given single-character string."""
    assert first_non_repeating_character("z") == "z"  # z:0+1=1 => first 1 => "z"


def test_issue_all_unique_returns_first_character():
    """Find the first non-repeated character returns the first when all are unique."""
    assert first_non_repeating_character("abcdef") == "a"  # 6 chars each 0+1=1 => first 1 => "a"


def test_issue_unique_at_start_returns_first():
    """Find the first non-repeated character at the start of the string."""
    assert first_non_repeating_character("zabcabc") == "z"  # z:0+1=1, a:1+1=2, b:1+1=2, c:1+1=2 => "z"


def test_issue_unique_at_end_returns_last():
    """Find the first non-repeated character at the end of the string."""
    assert first_non_repeating_character("aabbc") == "c"  # a:1+1=2, b:1+1=2, c:0+1=1 => "c"


def test_issue_unique_in_middle_returns_middle():
    """Find the first non-repeated character in the middle of the string."""
    assert first_non_repeating_character("aabcc") == "b"  # a:1+1=2, b:0+1=1, c:1+1=2 => "b"


def test_issue_first_occurrence_order_preserved():
    """Find the first non-repeated character in order of first appearance."""
    assert first_non_repeating_character("abccbd") == "a"  # a:0+1=1, b:1+1=2, c:1+1=2, d:0+1=1 => first 1 is "a"


def test_issue_triple_repeat_still_repeated():
    """Find the first non-repeated character treats 3 occurrences as repeated."""
    assert first_non_repeating_character("aaabccc") == "b"  # a:2+1=3, b:0+1=1, c:2+1=3 => "b"


def test_issue_palindrome_all_repeated_returns_none():
    """Find the first non-repeated character returns None when every character repeats."""
    assert first_non_repeating_character("abccba") is None  # a:1+1=2, b:1+1=2, c:1+1=2 => no 1s => None


def test_contract_function_is_callable():
    """Public interface exposes first_non_repeating_character(str1) as callable."""
    assert callable(first_non_repeating_character) is True  # check 1==1 => True


def test_contract_found_result_has_length_one():
    """Returned non-repeated character must be a single character string."""
    assert len(first_non_repeating_character("abcdabc")) == 1  # a:1+1=2, b:1+1=2, c:1+1=2, d:0+1=1 => len("d")==0+1==1
